import java.util.*;

public class Main {
    static class Edge {
        int to, rev;
        long cap;
        Edge(int t, int r, long c) {
            to = t;
            rev = r;
            cap = c;
        }
    }

    static class Dinic {
        int n, s, t;
        ArrayList<ArrayList<Edge>> g;
        int[] level, it;

        Dinic(int n, int s, int t) {
            this.n = n;
            this.s = s;
            this.t = t;
            g = new ArrayList<>(n);
            for (int i = 0; i < n; i++) g.add(new ArrayList<>());
            level = new int[n];
            it = new int[n];
        }

        void add(int u, int v, long c) {
            g.get(u).add(new Edge(v, g.get(v).size(), c));
            g.get(v).add(new Edge(u, g.get(u).size() - 1, 0));
        }

        boolean bfs() {
            Arrays.fill(level, -1);
            Queue<Integer> q = new LinkedList<>();
            level[s] = 0;
            q.add(s);
            while (!q.isEmpty()) {
                int u = q.poll();
                for (Edge e : g.get(u)) {
                    if (e.cap > 0 && level[e.to] == -1) {
                        level[e.to] = level[u] + 1;
                        q.add(e.to);
                    }
                }
            }
            return level[t] != -1;
        }

        long dfs(int u, long f) {
            if (u == t) return f;
            for (int i = it[u]; i < g.get(u).size(); i++) {
                it[u] = i;
                Edge e = g.get(u).get(i);
                if (e.cap > 0 && level[e.to] == level[u] + 1) {
                    long ret = dfs(e.to, Math.min(f, e.cap));
                    if (ret > 0) {
                        e.cap -= ret;
                        g.get(e.to).get(e.rev).cap += ret;
                        return ret;
                    }
                }
            }
            return 0;
        }

        long flow() {
            long ans = 0;
            while (bfs()) {
                Arrays.fill(it, 0);
                long f;
                while ((f = dfs(s, (long) 1e18)) > 0) ans += f;
            }
            return ans;
        }
    }

    static void dfsTempo(int i, int j, String[] sc, int n, int cur, int[][] tempo) {
        if (i < 0 || i >= n || j < 0 || j >= n) return;
        char c = sc[i].charAt(j);
        if (!Character.isDigit(c) && c != 'Z') return;
        if (tempo[i][j] != -1 && tempo[i][j] <= cur) return;
        tempo[i][j] = (tempo[i][j] == -1) ? cur : Math.min(tempo[i][j], cur);
        dfsTempo(i + 1, j, sc, n, cur + 1, tempo);
        dfsTempo(i - 1, j, sc, n, cur + 1, tempo);
        dfsTempo(i, j + 1, sc, n, cur + 1, tempo);
        dfsTempo(i, j - 1, sc, n, cur + 1, tempo);
    }

    static void dfsAlc(int i, int j, String[] sc, int n, int cur, int[][] alc) {
        if (i < 0 || i >= n || j < 0 || j >= n) return;
        if (!Character.isDigit(sc[i].charAt(j))) return;
        if (alc[i][j] != -1 && alc[i][j] <= cur) return;
        alc[i][j] = (alc[i][j] == -1) ? cur : Math.min(alc[i][j], cur);
        dfsAlc(i + 1, j, sc, n, cur + 1, alc);
        dfsAlc(i - 1, j, sc, n, cur + 1, alc);
        dfsAlc(i, j + 1, sc, n, cur + 1, alc);
        dfsAlc(i, j - 1, sc, n, cur + 1, alc);
    }

    public static void main(String[] args) {
        new Thread(null, new Runnable() {
            public void run() {
                solve();
            }
        }, "Main", 1 << 28).start();
    }

    static void solve() {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int t = sc.nextInt();
        int n2 = n * n;
        int total = n2 * 2 + 2;
        Dinic din = new Dinic(total, 0, total - 1);

        String[] grid = new String[n];
        String[] caps = new String[n];
        int[][] pos = new int[n][n];
        int cnt = 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                pos[i][j] = cnt++;
            }
        }

        int zi = 0, zj = 0;
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next();
            for (int j = 0; j < n; j++) {
                if (grid[i].charAt(j) == 'Z') {
                    zi = i;
                    zj = j;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            caps[i] = sc.next();
        }

        int[][] tempo = new int[n][n];
        for (int i = 0; i < n; i++) Arrays.fill(tempo[i], -1);
        dfsTempo(zi, zj, grid, n, 0, tempo);

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (tempo[i][j] == -1 && Character.isDigit(grid[i].charAt(j))) {
                    tempo[i][j] = t;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (Character.isDigit(grid[i].charAt(j))) {
                    int lim = grid[i].charAt(j) - '0';
                    din.add(0, pos[i][j], lim);
                    int[][] alc = new int[n][n];
                    for (int k = 0; k < n; k++) Arrays.fill(alc[k], -1);
                    dfsAlc(i, j, grid, n, 0, alc);
                    for (int k = 0; k < n; k++) {
                        for (int l = 0; l < n; l++) {
                            if (alc[k][l] != -1 && tempo[k][l] != -1 &&
                                alc[k][l] <= tempo[k][l] && alc[k][l] <= t) {
                                boolean ok = true;
                                if (alc[k][l] == tempo[k][l]) {
                                    ok = false;
                                    if (k + 1 < n && alc[k + 1][l] != -1 && alc[k + 1][l] < tempo[k + 1][l]) ok = true;
                                    if (k - 1 >= 0 && alc[k - 1][l] != -1 && alc[k - 1][l] < tempo[k - 1][l]) ok = true;
                                    if (l + 1 < n && alc[k][l + 1] != -1 && alc[k][l + 1] < tempo[k][l + 1]) ok = true;
                                    if (l - 1 >= 0 && alc[k][l - 1] != -1 && alc[k][l - 1] < tempo[k][l - 1]) ok = true;
                                }
                                if (ok) {
                                    din.add(pos[i][j], n2 + pos[k][l], lim);
                                }
                            }
                        }
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (Character.isDigit(caps[i].charAt(j))) {
                    din.add(n2 + pos[i][j], total - 1, caps[i].charAt(j) - '0');
                }
            }
        }

        System.out.println(din.flow());
    }
}
